import dotenv from "dotenv";
import express from "express";
import path from "path";
import { createServer as createViteServer } from "vite";

// Load environment variables from .env.local
dotenv.config({ path: '.env.local' });

async function startServer() {
  const app = express();
  const PORT = 3000;

  app.use(express.json());

  // API Route to proxy discord webhooks
  app.post("/api/notify-discord", async (req, res) => {
    try {
      const { type, content } = req.body;
      console.log("Webhook request received. Type:", type);
      console.log("DISCORD_WEBHOOK_SUBMISSIONS env:", process.env.DISCORD_WEBHOOK_SUBMISSIONS ? "✓ Set" : "✗ Not set");
      
      const webhookUrl = type === 'prompt' 
        ? process.env.DISCORD_WEBHOOK_PROMPTS 
        : process.env.DISCORD_WEBHOOK_SUBMISSIONS;

      if (!webhookUrl) {
        console.error("No webhook URL configured for type:", type);
        // Silently ignore if no webhook is set
        return res.json({ status: "skipped", reason: `No webhook URL configured for type ${type}` });
      }

      if (!content) {
        return res.status(400).json({ error: "Missing content" });
      }

      console.log("Sending webhook to Discord...");
      const response = await fetch(webhookUrl, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ content })
      });

      if (!response.ok) {
        const errorText = await response.text();
        console.error("Discord Webhook Error:", response.status, errorText);
        return res.status(500).json({ error: "Failed to send to Discord" });
      }

      console.log("✓ Successfully sent webhook to Discord");
      res.json({ status: "ok" });
    } catch (e) {
      console.error("Failed to notify discord", e);
      res.status(500).json({ error: "Internal Server Error" });
    }
  });

  // Vite middleware for development
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    app.use(express.static("dist"));
    app.get("*", (req, res) => {
      res.sendFile(path.join(process.cwd(), "dist", "index.html"));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server running on http://localhost:${PORT}`);
  });
}

startServer();
